CREATE DATABASE IF NOT EXISTS kroma CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kroma;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS auditoria, consultas_soporte, favoritos, pagos, historial_pedidos, detalle_pedido, pedidos, movimientos_inventario, unidades_usadas, inventario, promociones, especificaciones_producto, producto_fuente_imagen, imagenes_producto, producto_categoria, detalle_carrito, carritos, productos, marcas, categorias, configuracion_envio, sucursales, direcciones, usuarios, roles;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE roles(id_rol INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(30) NOT NULL UNIQUE,descripcion VARCHAR(255),estado TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE usuarios(id_usuario INT AUTO_INCREMENT PRIMARY KEY,id_rol INT NOT NULL,nombre VARCHAR(100) NOT NULL,apellido VARCHAR(100) NOT NULL DEFAULT '',email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,telefono VARCHAR(30),dni VARCHAR(8) UNIQUE,estado TINYINT NOT NULL DEFAULT 1,email_verificado TINYINT NOT NULL DEFAULT 0,token_sesion CHAR(64),sesion_actividad DATETIME,fecha_registro DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,fecha_ultimo_acceso DATETIME,FOREIGN KEY(id_rol) REFERENCES roles(id_rol)) ENGINE=InnoDB;
CREATE TABLE consultas_soporte(id_consulta BIGINT AUTO_INCREMENT PRIMARY KEY,id_usuario INT NULL,nombre VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,tipo VARCHAR(60) NOT NULL,asunto VARCHAR(180) NOT NULL,mensaje TEXT NOT NULL,estado ENUM('nuevo','en_revision','resuelto') NOT NULL DEFAULT 'nuevo',fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_soporte_estado_fecha(estado,fecha_creacion),INDEX idx_soporte_email(email),FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE direcciones(id_direccion INT AUTO_INCREMENT PRIMARY KEY,id_usuario INT NOT NULL,alias VARCHAR(60),calle VARCHAR(120) NOT NULL,numero VARCHAR(20) NOT NULL,piso_departamento VARCHAR(50),ciudad VARCHAR(100) NOT NULL,provincia VARCHAR(100) NOT NULL,codigo_postal VARCHAR(20) NOT NULL,referencia VARCHAR(255),es_principal TINYINT NOT NULL DEFAULT 0,fecha_registro DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE categorias(id_categoria INT AUTO_INCREMENT PRIMARY KEY,id_categoria_padre INT,nombre VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,descripcion TEXT,imagen VARCHAR(255),estado TINYINT NOT NULL DEFAULT 1,orden_visualizacion INT NOT NULL DEFAULT 0,FOREIGN KEY(id_categoria_padre) REFERENCES categorias(id_categoria) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE marcas(id_marca INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,slug VARCHAR(120) NOT NULL UNIQUE,descripcion TEXT,estado TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE productos(id_producto INT AUTO_INCREMENT PRIMARY KEY,id_categoria INT NOT NULL,id_marca INT NOT NULL,nombre VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,modelo VARCHAR(120) NOT NULL,descripcion TEXT,tipo_producto VARCHAR(40) NOT NULL DEFAULT 'nuevo',condicion ENUM('nuevo','usado','reacondicionado') NOT NULL DEFAULT 'nuevo',precio DECIMAL(12,2) NOT NULL,precio_anterior DECIMAL(12,2),garantia_meses SMALLINT NOT NULL DEFAULT 0,estado TINYINT NOT NULL DEFAULT 1,publicado TINYINT NOT NULL DEFAULT 1,fecha_publicacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_producto_categoria(id_categoria),INDEX idx_producto_marca(id_marca),INDEX idx_producto_estado(estado,publicado),CHECK(precio>=0),CHECK(precio_anterior IS NULL OR precio_anterior>=precio),FOREIGN KEY(id_categoria) REFERENCES categorias(id_categoria),FOREIGN KEY(id_marca) REFERENCES marcas(id_marca)) ENGINE=InnoDB;
CREATE TABLE producto_categoria(id_producto INT NOT NULL,id_categoria INT NOT NULL,PRIMARY KEY(id_producto,id_categoria),FOREIGN KEY(id_producto) REFERENCES productos(id_producto) ON DELETE CASCADE,FOREIGN KEY(id_categoria) REFERENCES categorias(id_categoria)) ENGINE=InnoDB;
CREATE TABLE imagenes_producto(id_imagen INT AUTO_INCREMENT PRIMARY KEY,id_producto INT NOT NULL,ruta_imagen VARCHAR(2048) NOT NULL,texto_alternativo VARCHAR(180) NOT NULL,es_principal TINYINT NOT NULL DEFAULT 0,orden INT NOT NULL DEFAULT 0,FOREIGN KEY(id_producto) REFERENCES productos(id_producto) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE producto_fuente_imagen(id_producto INT PRIMARY KEY,url_fuente VARCHAR(500) NOT NULL,FOREIGN KEY(id_producto) REFERENCES productos(id_producto) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE especificaciones_producto(id_especificacion INT AUTO_INCREMENT PRIMARY KEY,id_producto INT NOT NULL,atributo VARCHAR(100) NOT NULL,valor VARCHAR(255) NOT NULL,unidad VARCHAR(40),FOREIGN KEY(id_producto) REFERENCES productos(id_producto) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE promociones(id_promocion INT AUTO_INCREMENT PRIMARY KEY,id_producto INT NOT NULL,precio_promocional DECIMAL(12,2) NOT NULL,fecha_inicio DATETIME NOT NULL,fecha_fin DATETIME NOT NULL,estado TINYINT NOT NULL DEFAULT 1,CHECK(precio_promocional>=0),CHECK(fecha_fin>fecha_inicio),FOREIGN KEY(id_producto) REFERENCES productos(id_producto)) ENGINE=InnoDB;
CREATE TABLE inventario(id_inventario INT AUTO_INCREMENT PRIMARY KEY,id_producto INT NOT NULL UNIQUE,cantidad_disponible INT NOT NULL DEFAULT 0,cantidad_reservada INT NOT NULL DEFAULT 0,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CHECK(cantidad_disponible>=0),CHECK(cantidad_reservada>=0),FOREIGN KEY(id_producto) REFERENCES productos(id_producto)) ENGINE=InnoDB;
CREATE TABLE unidades_usadas(id_unidad_usada INT AUTO_INCREMENT PRIMARY KEY,id_producto INT NOT NULL,codigo_unidad VARCHAR(80) NOT NULL UNIQUE,estado_conservacion VARCHAR(100) NOT NULL,descripcion_estado TEXT,precio_especifico DECIMAL(12,2),garantia_meses SMALLINT NOT NULL DEFAULT 0,estado_disponibilidad ENUM('disponible','vendida','retirada') NOT NULL DEFAULT 'disponible',fecha_ingreso DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_producto) REFERENCES productos(id_producto)) ENGINE=InnoDB;
CREATE TABLE carritos(id_carrito INT AUTO_INCREMENT PRIMARY KEY,id_usuario INT NOT NULL,estado ENUM('activo','convertido','abandonado') NOT NULL DEFAULT 'activo',fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario)) ENGINE=InnoDB;
CREATE TABLE detalle_carrito(id_detalle_carrito INT AUTO_INCREMENT PRIMARY KEY,id_carrito INT NOT NULL,id_producto INT NOT NULL,cantidad INT NOT NULL,fecha_agregado DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_carrito_producto(id_carrito,id_producto),CHECK(cantidad>0),FOREIGN KEY(id_carrito) REFERENCES carritos(id_carrito) ON DELETE CASCADE,FOREIGN KEY(id_producto) REFERENCES productos(id_producto)) ENGINE=InnoDB;
CREATE TABLE sucursales(id_sucursal INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,direccion VARCHAR(255),ciudad VARCHAR(100),provincia VARCHAR(100),telefono VARCHAR(30),estado TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE configuracion_envio(id_configuracion INT AUTO_INCREMENT PRIMARY KEY,modalidad VARCHAR(40) NOT NULL,costo DECIMAL(12,2) NOT NULL,activo TINYINT NOT NULL DEFAULT 1,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CHECK(costo>=0)) ENGINE=InnoDB;
CREATE TABLE pedidos(id_pedido INT AUTO_INCREMENT PRIMARY KEY,numero_pedido VARCHAR(40) NOT NULL UNIQUE,id_usuario INT NOT NULL,estado ENUM('pendiente','confirmado','preparando','listo_retiro','despachado','entregado','cancelado') NOT NULL,subtotal DECIMAL(12,2) NOT NULL,descuento_total DECIMAL(12,2) NOT NULL DEFAULT 0,costo_envio DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL,modalidad_entrega ENUM('retiro','envio') NOT NULL,id_direccion INT,datos_destinatario_historicos VARCHAR(220) NOT NULL,dni_destinatario_historico VARCHAR(8),ciudad_destinatario_historica VARCHAR(100),codigo_postal_destinatario_historico VARCHAR(10),direccion_entrega_historica TEXT,fecha_pedido DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,fecha_cancelacion DATETIME,motivo_cancelacion VARCHAR(255),INDEX idx_pedido_estado_fecha(estado,fecha_pedido),FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario),FOREIGN KEY(id_direccion) REFERENCES direcciones(id_direccion) ON DELETE SET NULL,CHECK(subtotal>=0 AND descuento_total>=0 AND costo_envio>=0 AND total>=0)) ENGINE=InnoDB;
CREATE TABLE detalle_pedido(id_detalle_pedido INT AUTO_INCREMENT PRIMARY KEY,id_pedido INT NOT NULL,id_producto INT NOT NULL,id_unidad_usada INT UNIQUE,nombre_producto_historico VARCHAR(180) NOT NULL,modelo_historico VARCHAR(120),precio_unitario DECIMAL(12,2) NOT NULL,cantidad INT NOT NULL,descuento_unitario DECIMAL(12,2) NOT NULL DEFAULT 0,subtotal_linea DECIMAL(12,2) NOT NULL,FOREIGN KEY(id_pedido) REFERENCES pedidos(id_pedido),FOREIGN KEY(id_producto) REFERENCES productos(id_producto),FOREIGN KEY(id_unidad_usada) REFERENCES unidades_usadas(id_unidad_usada),CHECK(precio_unitario>=0 AND cantidad>0 AND descuento_unitario>=0 AND subtotal_linea>=0)) ENGINE=InnoDB;
CREATE TABLE historial_pedidos(id_historial INT AUTO_INCREMENT PRIMARY KEY,id_pedido INT NOT NULL,id_usuario_responsable INT,estado_anterior VARCHAR(30),estado_nuevo VARCHAR(30) NOT NULL,observacion VARCHAR(255),fecha_cambio DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_pedido) REFERENCES pedidos(id_pedido),FOREIGN KEY(id_usuario_responsable) REFERENCES usuarios(id_usuario) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE pagos(id_pago INT AUTO_INCREMENT PRIMARY KEY,id_pedido INT NOT NULL,metodo_pago VARCHAR(40) NOT NULL,importe DECIMAL(12,2) NOT NULL,estado_pago ENUM('pendiente','aprobado','rechazado','cancelado') NOT NULL,referencia_operacion VARCHAR(100),fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_procesamiento DATETIME,UNIQUE KEY uq_pago_pedido(id_pedido),CHECK(importe>=0),FOREIGN KEY(id_pedido) REFERENCES pedidos(id_pedido)) ENGINE=InnoDB;
CREATE TABLE movimientos_inventario(id_movimiento INT AUTO_INCREMENT PRIMARY KEY,id_producto INT NOT NULL,id_unidad_usada INT,tipo_movimiento ENUM('entrada','salida','devolucion','ajuste') NOT NULL,cantidad INT NOT NULL,motivo VARCHAR(255) NOT NULL,id_usuario_responsable INT,id_pedido INT,fecha_movimiento DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_producto) REFERENCES productos(id_producto),FOREIGN KEY(id_unidad_usada) REFERENCES unidades_usadas(id_unidad_usada),FOREIGN KEY(id_usuario_responsable) REFERENCES usuarios(id_usuario) ON DELETE SET NULL,FOREIGN KEY(id_pedido) REFERENCES pedidos(id_pedido)) ENGINE=InnoDB;
CREATE TABLE notificaciones_administrador(id_notificacion BIGINT AUTO_INCREMENT PRIMARY KEY,id_producto INT,id_pedido INT,titulo VARCHAR(180) NOT NULL,mensaje VARCHAR(500) NOT NULL,leida TINYINT NOT NULL DEFAULT 0,fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_notificacion_leida_fecha(leida,fecha_creacion),FOREIGN KEY(id_producto) REFERENCES productos(id_producto) ON DELETE SET NULL,FOREIGN KEY(id_pedido) REFERENCES pedidos(id_pedido) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE favoritos(id_favorito INT AUTO_INCREMENT PRIMARY KEY,id_usuario INT NOT NULL,id_producto INT NOT NULL,fecha_agregado DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_favorito_usuario_producto(id_usuario,id_producto),FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario) ON DELETE CASCADE,FOREIGN KEY(id_producto) REFERENCES productos(id_producto)) ENGINE=InnoDB;
CREATE TABLE auditoria(id_auditoria INT AUTO_INCREMENT PRIMARY KEY,id_usuario INT,accion VARCHAR(80) NOT NULL,entidad VARCHAR(80) NOT NULL,id_registro_afectado INT,descripcion VARCHAR(255) NOT NULL,fecha_evento DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario) ON DELETE SET NULL) ENGINE=InnoDB;
DELIMITER $$
CREATE TRIGGER trg_movimiento_auditoria AFTER INSERT ON movimientos_inventario FOR EACH ROW BEGIN INSERT INTO auditoria(id_usuario,accion,entidad,id_registro_afectado,descripcion) VALUES(NEW.id_usuario_responsable,'movimiento_inventario','movimientos_inventario',NEW.id_movimiento,CONCAT(NEW.tipo_movimiento,' producto ',NEW.id_producto,', cantidad ',NEW.cantidad,': ',NEW.motivo)); END$$
DELIMITER ;
